   display: inline-flex;
    align-items: center;
    gap: 8px;
    height: 42px;
    padding: 0 22px;
    border-radius: 10px;
    font-size: 14px;
    font-weight: 700;
    text-decoration: none !important;
    transition: all 0.2s ease;
    cursor: pointer;
    box-shadow: none !important;
}

/* Ler Primeiro: Rosa Sólido Flat */
.btn-hero-action.btn-read-first {
    background: #fc81bb;
    color: #ffffff !important;
    border: none;
}

.btn-hero-action.btn-read-first:hover {
    background: #e66ea4;
    color: #ffffff !important;
    transform: translateY(-2px);
}

/* Ler Último: Dark Flat com Borda Rosa */
.btn-hero-action.btn-read-last {
    background: #111111;
    color: #fc81bb !important;
    border: 2px solid #fc81bb;
}

.btn-hero-action.btn-read-last:hover {
    background: #fc81bb;
    border-color: #fc81bb;
    color: #ffffff !important;
    transform: translateY(-2px);
}

/* Continuar Lendo: Lilás Sólido Flat */
.btn-hero-action.btn-read-continue {
    background: #cf9e

  border-radius: 6px;
    border: 1px solid #282828;
    text-decoration: none;
    transition: all 0.2s;
}

.manga-hero-tags .tags-cloud-wrap a:hover {
    background: #fc81bb;
    color: #ffffff;
    border-color: #fc81bb;
}

